package org.strongswan.android.rookstride;
import org.json.*;import org.junit.Test;import static org.junit.Assert.*;import java.util.*;
public class OwnerRecoveryTest {
 private JSONObject archive()throws Exception{String id="a".repeat(32);JSONObject nodes=new JSONObject();for(String role:new String[]{"entry","exit"})nodes.put(role,new JSONObject().put("schema",1).put("purpose","rookstride-owner-recovery-node").put("deployment",id).put("role",role).put("state",new JSONObject().put("private","secret-fixture")));return new JSONObject().put("schema",1).put("purpose","rookstride-owner-recovery").put("deployment",id).put("nodes",nodes);}
 @Test public void portableBackupDecryptsOnAnotherCallAndDoesNotRevealSecrets()throws Exception{JSONObject a=archive();char[] password="correct horse owner recovery".toCharArray();byte[] file=OwnerRecovery.encrypt(a,password),second=OwnerRecovery.encrypt(a,password);assertFalse(Arrays.equals(file,second));assertFalse(new String(file,java.nio.charset.StandardCharsets.ISO_8859_1).contains("secret-fixture"));assertEquals("secret-fixture",OwnerRecovery.decrypt(file,password,a.getString("deployment")).getJSONObject("nodes").getJSONObject("entry").getJSONObject("state").getString("private"));}
 @Test public void wrongPasswordTamperingWrongDeploymentAndInvitationPurposeFail()throws Exception{JSONObject a=archive();char[] password="correct horse owner recovery".toCharArray();byte[] file=OwnerRecovery.encrypt(a,password);try{OwnerRecovery.decrypt(file,"incorrect owner recovery".toCharArray(),a.getString("deployment"));fail();}catch(javax.crypto.AEADBadTagException expected){}byte[] changed=file.clone();changed[30]^=1;try{OwnerRecovery.decrypt(changed,password,a.getString("deployment"));fail();}catch(javax.crypto.AEADBadTagException expected){}try{OwnerRecovery.decrypt(file,password,"b".repeat(32));fail();}catch(java.io.IOException expected){}a.put("purpose","rookstride.admin.invitation");try{OwnerRecovery.encrypt(a,password);fail();}catch(java.io.IOException expected){}}
 @Test public void incompleteRecoveryAndUnboundedWorkFactorsAreRejectedBeforeDestructiveWork()throws Exception{JSONObject a=archive();char[] password="correct horse owner recovery".toCharArray();byte[] file=OwnerRecovery.encrypt(a,password);file[8]=127;try{OwnerRecovery.decrypt(file,password,a.getString("deployment"));fail();}catch(java.io.IOException expected){}a.getJSONObject("nodes").remove("exit");try{OwnerRecovery.encrypt(a,password);fail();}catch(JSONException expected){}try{OwnerRecovery.encrypt(archive(),"weak".toCharArray());fail();}catch(java.io.IOException expected){}}
 @Test public void soleManagementRelayIsAlwaysLastAndUnprovenPathsAreDenied()throws Exception{assertArrayEquals(new String[]{"exit","entry"},PairedOsReinstall.order("direct"));assertArrayEquals(new String[]{"exit","entry"},PairedOsReinstall.order("exit-via-entry"));assertArrayEquals(new String[]{"entry","exit"},PairedOsReinstall.order("entry-via-exit"));for(String route:new String[]{"auto","","vpn-only","none"})try{PairedOsReinstall.order(route);fail();}catch(java.io.IOException expected){}}
 @Test public void entryMigrationDisclosesLiteralIpAndProtocolLimitations()throws Exception{Gateway pair=new Gateway();pair.exit=new Gateway();pair.set("host","192.0.2.1");pair.set("vpnServer","192.0.2.1");pair.set("pairEngine","native-v2");pair.set("pairEntryProtocol","awg");pair.set("pairExitProtocol","awg");Gateway candidate=new Gateway();candidate.set("fingerprint","SHA256:"+"A".repeat(43));JSONObject literal=EntryMigrationController.preview(pair,candidate,false);assertFalse(literal.getBoolean("supported"));assertTrue(literal.getBoolean("client_update_required"));assertTrue(EntryMigrationController.preview(pair,candidate,true).getBoolean("supported"));pair.set("vpnServer","vpn.example.net");assertTrue(EntryMigrationController.preview(pair,candidate,false).getBoolean("supported"));pair.set("pairEntryProtocol","ikev2");assertTrue(EntryMigrationController.preview(pair,candidate,false).getBoolean("supported"));pair.set("vpnServer","192.0.2.1");candidate.set("host","192.0.2.9");JSONObject update=EntryMigrationController.preview(pair,candidate,false,true);assertTrue(update.getBoolean("supported"));assertTrue(update.getBoolean("client_update_required"));assertFalse(update.getBoolean("preserves_profiles"));assertFalse(update.getBoolean("requires_endpoint_switch"));assertEquals("192.0.2.9",update.getString("endpoint"));}

 @Test public void completedPairedWipeResumeNeverInvokesAnotherEraseGuard()throws Exception{Gateway pair=new Gateway();pair.exit=new Gateway();pair.set("pairId","a".repeat(32));JSONObject operation=new JSONObject().put("schema",1).put("mode","clean").put("operation","b".repeat(32)).put("deployment",pair.get("pairId")).put("expected_revision",1).put("route","direct").put("order",new JSONArray(new String[]{"exit","entry"})).put("verified",new JSONArray(new String[]{"exit","entry"})).put("phase","clean-nodes-ready");pair.data.put("pairedOsOperation",operation);for(int i=0;i<2;i++){JSONObject result=PairedOsReinstall.run(pair,null,true,()->{throw new AssertionError("No remote adapter is opened after both nodes verify");},phase->{},()->{},()->{throw new AssertionError("A completed resume cannot erase another node");});assertEquals("clean-nodes-ready",result.getString("state"));assertEquals(2,pair.data.getInt("deploymentRevision"));}}

 private Gateway restorePair()throws Exception{Gateway pair=new Gateway();pair.exit=new Gateway();pair.set("pairId","a".repeat(32));pair.set("host","192.0.2.1");pair.exit.set("host","192.0.2.2");pair.set("pairEngine","native-v2");pair.set("pairEntryProtocol","awg");pair.set("pairExitProtocol","awg");return pair;}
 private JSONObject restoreArchive(Gateway pair)throws Exception{JSONObject value=archive();for(String role:new String[]{"entry","exit"}){JSONObject node=value.getJSONObject("nodes").getJSONObject(role);node.getJSONObject("state").put("protocol",role.equals("entry")?pair.get("pairEntryProtocol"):pair.get("pairExitProtocol")).put("initialLogin","phone");node.put("initial_user",new JSONObject().put("login","phone").put("password","restoration fixture"));node.put("plan",PairController.request(pair,role).put("client_pool","10.66.0.0/24").put("test_ip","10.249.255.254").put("entry_address","10.253.0.2/30").put("exit_address","10.253.0.1/30").put("route_table",51831));}return value;}
 private void refusesBeforeAnyErase(Gateway pair,JSONObject value)throws Exception{PairController.Bundle unopened=()->{throw new AssertionError("No remote adapter may open for an incompatible archive");};try{PairedOsReinstall.runRestore(pair,new JSONObject().put("mode","restore"),false,value,unopened,unopened,phase->{},()->{throw new AssertionError("No destructive checkpoint may be persisted");},()->{throw new AssertionError("No erase may be attempted");});fail();}catch(java.io.IOException expected){}assertFalse(pair.data.has("pairedOsOperation"));}
 @Test public void missingBootstrapAndStaleEndpointAreRejectedBeforeAnyErase()throws Exception{Gateway pair=restorePair();JSONObject valid=restoreArchive(pair);OwnerRecovery.validateRestore(pair,valid);JSONObject missing=new JSONObject(valid.toString());missing.getJSONObject("nodes").getJSONObject("entry").remove("initial_user");refusesBeforeAnyErase(pair,missing);JSONObject stale=new JSONObject(valid.toString());stale.getJSONObject("nodes").getJSONObject("exit").getJSONObject("plan").put("exit_host","192.0.2.3");refusesBeforeAnyErase(pair,stale);pair.data.put("tunnelPort",8443);refusesBeforeAnyErase(pair,valid);}
 @Test public void oldReviewWithoutCrossMemberReadinessCannotStartErase()throws Exception{Gateway pair=restorePair();refusesBeforeAnyErase(pair,restoreArchive(pair));}
 @Test public void recoveryBootstrapUsesArchivedInitialAccountWithoutChangingSelectedPhoneAccount()throws Exception{
  Gateway pair=restorePair();pair.set("vpnLogin","later-selected-user");pair.vpnPassword="selected phone secret";pair.set("profileUuid","saved-profile-uuid");pair.data.put("rememberVpn",true).put("favorite",true);
  JSONObject value=restoreArchive(pair);String before=pair.persisted().toString(),beforeArchive=value.toString();
  // A cached account need not still be enabled on the server to permit owner recovery.
  OwnerRecovery.validateRestore(pair,value);
  for(int attempt=0;attempt<2;attempt++){
   JSONObject request=PairedOsReinstall.restoreBootstrapRequest(pair,"entry",value);
   assertEquals("bootstrap",request.getString("action"));assertEquals("entry",request.getString("role"));assertEquals("phone",request.getString("login"));assertEquals("restoration fixture",request.getString("password"));
   JSONObject exit=PairedOsReinstall.restoreBootstrapRequest(pair,"exit",value);assertFalse(exit.has("login"));assertFalse(exit.has("password"));
   assertEquals("later-selected-user",pair.get("vpnLogin"));assertEquals("selected phone secret",pair.vpnPassword);assertEquals("saved-profile-uuid",pair.get("profileUuid"));assertTrue(pair.data.getBoolean("favorite"));assertEquals(before,pair.persisted().toString());assertEquals(beforeArchive,value.toString());
  }
 }
 @Test public void unqualifiedExitMigrationRefusesBeforeCandidateOrJournalWork()throws Exception{Gateway pair=restorePair(),candidate=new Gateway();for(String entry:new String[]{"ikev2","openvpn","xray","xhttp","hysteria2","outline","shadowsocks","trusttunnel","naive"}){pair.set("pairEntryProtocol",entry);try{LifecycleController.replaceExit(pair,candidate,()->{throw new AssertionError("An unqualified migration cannot upload a candidate helper");},phase->{},()->{throw new AssertionError("An unqualified migration cannot save an operation");});fail();}catch(java.io.IOException expected){assertTrue(expected.getMessage().contains("Verify and pin"));}assertFalse(pair.data.has("lifecycleOperation"));}}

}
